#!/usr/bin/env bash
# Generated by gq (@getquick/site) from gq.ops.json; gq sync rewrites it.
#
# Request admission for a Site that guards Composer packages: while a deploy
# holds the Site, every PHP request the web server hands PHP-FPM is answered
# 503 before any other PHP code runs (WordPress, its installer and upgrader,
# setup-config, a plugin's own PHP file). Command-line PHP (WP-CLI, so the
# deploy and a recovery) is never held. Static files aren't PHP: the web
# server still serves them.
#
#   SITE_PATH=… APP_PATH=apps/cms admission.sh begin   # hold, and prove it
#   SITE_PATH=… APP_PATH=apps/cms admission.sh lift    # end the hold
#
# What it owns, all outside what Composer or the release's rsync write:
#   $SITE_PATH/.gq/admission.php  the gate (PHP's auto_prepend_file)
#   $SITE_PATH/.gq/hold           present: held; its content is this hold's
#                                 nonce (public freshness evidence, no secret)
#   a managed block in $SITE_PATH/$APP_PATH/web/.user.ini, which PHP-FPM
#   reads for every script under the web root; any other setting there stays
#
# `begin` writes the gate, the .user.ini block and the hold, reloads PHP-FPM
# (which must succeed), waits (bounded) until every PHP-FPM worker that ran
# before the reload has gone (finished or ended by the reload), so no request
# that started before the hold still runs, and then requires the web server
# itself, over TLS for the admin domain on this machine, to answer 503 with
# this hold's nonce for the front page and for setup-config.php. Every worker
# then serving started after the hold. Anything it can't prove fails, before
# any package file changes; a hold this attempt created is then removed (the
# Site's code is the previous, verified one), a hold an earlier failed deploy
# left stays.
set -euo pipefail

# gq.ops.json's domains.admin, if it is a plain hostname; empty otherwise.
ADMIN_HOST="{{domains.adminHost}}"
SITE_PATH="${SITE_PATH:-}"
APP_PATH="${APP_PATH:-apps/cms}"
# How long pre-hold workers may take to go, in seconds (1-600).
DRAIN_SECONDS="${GQ_ADMISSION_DRAIN_SECONDS:-120}"
PROBE_PATHS=("/" "/wp/wp-admin/setup-config.php")
BLOCK_BEGIN="; BEGIN GETQUICK request admission (deploy/ploi/admission.sh manages this block)"
BLOCK_END="; END GETQUICK request admission"

refuse() {
  echo "$1" >&2
  exit 1
}

case "$SITE_PATH" in
  /*) ;;
  *) refuse "admission.sh needs SITE_PATH, the Site's absolute path." ;;
esac
# Paths gq writes are plain: they appear in the .user.ini value.
[[ "$SITE_PATH" =~ ^/[A-Za-z0-9._/-]+$ && "$APP_PATH" =~ ^[A-Za-z0-9._/-]+$ ]] \
  || refuse "The Site's path has characters gq won't write into .user.ini."
case "$DRAIN_SECONDS" in
  '' | *[!0-9]*) refuse "GQ_ADMISSION_DRAIN_SECONDS isn't a number of seconds." ;;
esac
{ [ "$DRAIN_SECONDS" -ge 1 ] && [ "$DRAIN_SECONDS" -le 600 ]; } \
  || refuse "GQ_ADMISSION_DRAIN_SECONDS must be between 1 and 600."

GQ_DIR="$SITE_PATH/.gq"
GATE="$GQ_DIR/admission.php"
HOLD="$GQ_DIR/hold"
WEB="$SITE_PATH/$APP_PATH/web"
INI="$WEB/.user.ini"

# A path gq manages must be absent or a regular file (a directory for .gq),
# never a symlink.
plain_file() {
  if [ -L "$1" ] || { [ -e "$1" ] && [ ! -f "$1" ]; }; then
    refuse "$1 isn't a regular file gq can manage; nothing changed."
  fi
}
plain_directory() {
  if [ -L "$1" ] || { [ -e "$1" ] && [ ! -d "$1" ]; }; then
    refuse "$1 isn't a directory gq can manage; nothing changed."
  fi
}

# Replaces $1 with $2's content atomically (a rename in the same directory).
write_atomically() {
  local target="$1" temporary
  temporary="$(mktemp "$(dirname "$target")/.gq-admission.XXXXXX")"
  printf '%s' "$2" >"$temporary"
  chmod 0644 "$temporary"
  mv -f "$temporary" "$target"
}

gate_source() {
  cat <<'GQ_GATE'
<?php
// GETQUICK request admission (deploy/ploi/admission.sh): PHP-FPM runs this
// before every script under the web root. While a guarded deploy holds the
// Site (a hold file beside this one), every web request ends here, 503,
// before any other PHP code. Command-line PHP is never held.
if (PHP_SAPI !== 'cli' && PHP_SAPI !== 'phpdbg') {
    $gq_hold = __DIR__ . '/hold';
    clearstatcache(true, $gq_hold);
    if (is_file($gq_hold)) {
        $gq_nonce = trim((string) @file_get_contents($gq_hold, false, null, 0, 64));
        if (!headers_sent()) {
            http_response_code(503);
            header('Retry-After: 600');
            header('Cache-Control: no-store');
            header('Content-Type: text/plain; charset=utf-8');
            if (preg_match('/^[0-9a-f]{32}$/', $gq_nonce) === 1) {
                header('X-GQ-Hold: ' . $gq_nonce);
            }
        }
        echo "This site is temporarily unavailable.\n";
        exit;
    }
    unset($gq_hold);
}
GQ_GATE
}

ini_block() {
  printf '%s\nauto_prepend_file = "%s"\n%s\n' "$BLOCK_BEGIN" "$GATE" "$BLOCK_END"
}

# The .user.ini with gq's block: unchanged if it has it, the block appended
# if it has none, and refused if it prepends anything else.
ini_with_block() {
  local existing="" stripped
  [ -f "$INI" ] && existing="$(cat "$INI")"
  # Everything outside gq's block.
  stripped="$(printf '%s\n' "$existing" | awk -v b="$BLOCK_BEGIN" -v e="$BLOCK_END" '
    $0 == b { inside = 1; next } $0 == e { inside = 0; next } !inside { print }')"
  if printf '%s\n' "$stripped" | grep -Eqi '^[[:space:]]*auto_prepend_file[[:space:]]*='; then
    refuse "$INI already sets auto_prepend_file; gq won't replace or chain unknown prepend code (a reviewed migration must move it). Nothing changed."
  fi
  if printf '%s\n' "$existing" | grep -qxF "$BLOCK_BEGIN"; then
    local block
    block="$(printf '%s\n' "$existing" | awk -v b="$BLOCK_BEGIN" -v e="$BLOCK_END" '
      $0 == b { inside = 1 } inside { print } $0 == e { inside = 0 }')"
    [ "$block" = "$(ini_block)" ] \
      || refuse "$INI has a GETQUICK block gq didn't write; nothing changed."
    printf '%s' "$existing"
    [ -z "$existing" ] || printf '\n'
    return
  fi
  if [ -n "$existing" ]; then printf '%s\n\n' "$existing"; fi
  ini_block
}

# PHP-FPM's processes (named php-fpm*, so never the command that lists them)
# as "<pid> <ppid> <name> <start time> <args>".
fpm_processes() {
  ps -e -o pid= -o ppid= -o comm= -o lstart= -o args= 2>/dev/null | awk '$3 ~ /^php-fpm/' || true
}

# The workers of PHP-FPM $PHP_VERSION (the pools of the master the reload
# restarts; another PHP version's master isn't reloaded, so its workers are
# none of this), as "<pid> <start time>", one per line.
fpm_workers() {
  fpm_processes | awk -v master="php-fpm: master process (/etc/php/$PHP_VERSION/fpm/php-fpm.conf)" '
    { line[NR] = $0; ppid[NR] = $2 }
    index($0, master) { masters[$1] = 1 }
    END {
      for (i = 1; i <= NR; i++) {
        if ((ppid[i] in masters) && index(line[i], "php-fpm: pool ")) {
          split(line[i], f, " ")
          print f[1], f[4], f[5], f[6], f[7], f[8]
        }
      }
    }'
}

# Which of $1's processes ("<pid> <start time>" lines) still run, wherever
# they are now (a worker whose master went is still running).
still_running() {
  comm -12 <(printf '%s\n' "$1" | grep . | sort) \
    <(ps -e -o pid= -o lstart= 2>/dev/null | awk '{ print $1, $2, $3, $4, $5, $6 }' | sort)
}

# Whether PHP-FPM $PHP_VERSION's master process is visible to this user.
fpm_master_visible() {
  fpm_processes | grep -qF "php-fpm: master process (/etc/php/$PHP_VERSION/fpm/php-fpm.conf)"
}

reload_fpm() {
  sudo -n service "php$PHP_VERSION-fpm" reload >/dev/null
}

# The response headers of a request to $1 on this machine's web server, for
# the admin domain, over TLS with its certificate checked; no redirect
# followed, no body kept.
probe() {
  curl --silent --show-error --output /dev/null --dump-header - \
    --proto '=https' --max-redirs 0 --connect-timeout 5 --max-time 15 \
    --resolve "$ADMIN_HOST:443:127.0.0.1" "https://$ADMIN_HOST$1"
}

begin() {
  [[ "$ADMIN_HOST" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$ ]] \
    || refuse "gq.ops.json domains.admin isn't a hostname the admission check can request; nothing changed."
  plain_directory "$GQ_DIR"
  plain_directory "$WEB"
  plain_file "$GATE"
  plain_file "$HOLD"
  plain_file "$INI"
  local ini changed=() prior_hold=false nonce old reason=""
  ini="$(ini_with_block)"
  PHP_VERSION="$(php -r 'echo PHP_MAJOR_VERSION . "." . PHP_MINOR_VERSION;')"
  [[ "$PHP_VERSION" =~ ^[0-9]+\.[0-9]+$ ]] || refuse "PHP's version can't be read; nothing changed."
  fpm_master_visible \
    || refuse "PHP-FPM $PHP_VERSION's master process isn't visible to this user, so gq can't tell when the workers that ran before a hold have gone; nothing changed."
  [ -f "$HOLD" ] && prior_hold=true

  mkdir -p "$GQ_DIR" "$WEB"
  if [ ! -f "$GATE" ] || [ "$(cat "$GATE")" != "$(gate_source)" ]; then
    write_atomically "$GATE" "$(gate_source)"$'\n'
    changed+=("the admission gate")
  fi
  if [ ! -f "$INI" ] || [ "$(cat "$INI")" != "${ini%$'\n'}" ]; then
    write_atomically "$INI" "$ini"
    changed+=("$APP_PATH/web/.user.ini")
  fi
  nonce="$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n')"
  write_atomically "$HOLD" "$nonce"$'\n'

  # Fails the attempt: a hold it created goes (no package file has changed,
  # so the Site's code is the previous, verified one); one an earlier failed
  # deploy left stays.
  fail() {
    local kept="The hold this attempt placed was removed."
    if [ "$prior_hold" = true ]; then
      kept="The hold an earlier failed deploy left stays."
    else
      rm -f "$HOLD"
    fi
    echo "The admission check failed: $1. No package file was changed; ${changed[*]:-nothing else} changed. $kept" >&2
    exit 1
  }

  old="$(fpm_workers)"
  reload_fpm || {
    changed+=("nothing in PHP-FPM (its reload failed)")
    fail "PHP-FPM couldn't be reloaded (sudo -n service php$PHP_VERSION-fpm reload), so workers started before the hold may still serve"
  }
  changed+=("a PHP-FPM reload")
  local deadline=$((SECONDS + DRAIN_SECONDS)) left
  while :; do
    left="$(still_running "$old" | grep -c . || true)"
    [ "$left" = 0 ] && break
    [ "$SECONDS" -lt "$deadline" ] \
      || fail "$left PHP-FPM $PHP_VERSION worker(s) that ran before the hold were still running after ${DRAIN_SECONDS}s"
    sleep 1
  done

  local path headers attempt
  for path in "${PROBE_PATHS[@]}"; do
    for attempt in 1 2 3; do
      if headers="$(probe "$path" 2>/dev/null)" \
        && printf '%s\n' "$headers" | head -n 1 | grep -Eq '^HTTP/[0-9.]+ 503( |$)' \
        && printf '%s\n' "$headers" | tr -d '\r' | grep -qix "x-gq-hold: $nonce"; then
        reason=""
        break
      fi
      reason="https://$ADMIN_HOST$path didn't answer 503 with this hold's nonce"
      sleep 1
    done
    [ -z "$reason" ] || fail "$reason"
  done
  [ -n "$(fpm_workers)" ] \
    || fail "no PHP-FPM $PHP_VERSION worker is visible to this user after the probes, so gq can't tell the pre-hold ones have gone"

  echo "Held: PHP-FPM reloaded, every worker that ran before the hold has gone, and the web server answers 503 with this hold's nonce ($nonce)."
}

lift() {
  plain_file "$HOLD"
  rm -f "$HOLD"
  echo "The hold is lifted: PHP requests are served again."
}

case "${1:-}" in
  begin) begin ;;
  lift) lift ;;
  *) refuse "Usage: admission.sh begin | lift" ;;
esac
